#ifndef TAPP_CON_CONSTRAINT_SOLVER_H
#define TAPP_CON_CONSTRAINT_SOLVER_H

#include <cstdint>
#include <vector>

#include "linear_constraint.h"

namespace tapp_con {

/// Describes a single block generated by the constraint solver.
struct BlockSpec {
    uint64_t row_offset;
    uint64_t col_offset;
    uint64_t num_rows;
    uint64_t num_cols;
    int32_t  u1_qnum;
    int32_t  su2_spin_times_two;
};

class ConstraintSolver {
public:
    /// Generate all valid BlockSpec entries from a constraint system.
    ///
    /// @param system      the constraint system (leg sectors + constraints)
    /// @param row_legs    indices of legs mapped to matrix rows
    /// @param col_legs    indices of legs mapped to matrix cols
    /// @param leg_dims    physical dimension per leg (uniform across sectors for that leg)
    /// @return vector of BlockSpec for all valid charge/spin assignments
    static std::vector<BlockSpec> generate_blocks(
        const ConstraintSystem& system,
        const std::vector<int>& row_legs,
        const std::vector<int>& col_legs,
        const std::vector<uint64_t>& leg_dims);

    /// Check if a specific assignment satisfies all constraints.
    static bool satisfies_constraints(
        const ConstraintSystem& system,
        const std::vector<int32_t>& leg_u1_qnums,
        const std::vector<int32_t>& leg_su2_spins_t2);

private:
    /// Recursive backtracking kernel
    static void backtrack(
        const ConstraintSystem& system,
        size_t leg_idx,
        std::vector<int32_t>& current_u1,
        std::vector<int32_t>& current_su2,
        const std::vector<int>& row_legs,
        const std::vector<int>& col_legs,
        const std::vector<uint64_t>& leg_dims,
        std::vector<BlockSpec>& out_blocks);
};

} // namespace tapp_con

#endif // TAPP_CON_CONSTRAINT_SOLVER_H
